def _replace_visible_terms(value: Any, replacements: list[tuple[str, str]], key: str = "") -> Any:
    """
    递归修正本地化正文中的少量可见词，同时保留路由和数据标识。

    :param value: 待处理的内容节点
    :param replacements: 需要替换的本地化词对
    :param key: 当前字典键名
    :return: 修正后的内容节点
    """
    if isinstance(value, dict):
        protected = {"target", "id", "path", "url", "slug"}
        return {
            item_key: item_value
            if item_key in protected
            else _replace_visible_terms(item_value, replacements, item_key)
            for item_key, item_value in value.items()
        }
    if isinstance(value, list):
        return [_replace_visible_terms(item, replacements, key) for item in value]
    if isinstance(value, str):
        for old, new in replacements:
            value = value.replace(old, new)
        return value
    return value


